    int largestSubstringLength = 0;

    // Iterate through each string in the list
    for (String string : strings) {
        // Iterate through each character in the string
        for (int i = 0; i < string.length(); i++) {
            // Check if the substring starting at index i is a substring of any of the other strings
            for (String otherString : strings) {
                if (otherString.contains(string.substring(i))) {
                    // If it is a substring, update the largest substring length
                    largestSubstringLength = Math.max(largestSubstringLength, string.substring(i).length());
                    break;
                }
            }
        }
    }

    // Return the largest substring length
    return largestSubstringLength;
