public static int countOilDeposits(char[][] grid) {
    int numDeposits = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@') {
                // Count this oil deposit
                numDeposits++;
                // Mark all connected oil deposits as visited
                markConnectedDeposits(grid, i, j);
            }
        }
    }
    return numDeposits;
}

private static void markConnectedDeposits(char[][] grid, int i, int j) {
    // Base case: out of bounds
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] != '@') {
        return;
    }
    // Mark this oil deposit as visited
    grid[i][j] = '-';
    // Recursively mark all connected oil deposits
    markConnectedDeposits(grid, i + 1, j);
    markConnectedDeposits(grid, i - 1, j);
    markConnectedDeposits(grid, i, j + 1);
    markConnectedDeposits(grid, i, j - 1);
}
