public static int countOilDeposits(char[][] grid) {
    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                if (i > 0 && grid[i - 1][j] == '@') continue;
                if (j > 0 && grid[i][j - 1] == '@') continue;
                if (i < rows - 1 && grid[i + 1][j] == '@') continue;
                if (j < cols - 1 && grid[i][j + 1] == '@') continue;
                count++;
            }
        }
    }

    return count;
}
