public static String canTravelMaze(int[] start, int[] end, int[][] paths) {
  // check if starting and ending n-tersections are within the bounds of the n-teresting space
  if (start[0] >= paths.length || start[1] >= paths[0].length ||
      end[0] >= paths.length || end[1] >= paths[0].length) {
    return "cannot be travelled";
  }

  // create a set to keep track of visited n-tersections
  Set<int[]> visited = new HashSet<>();

  // mark starting n-tersection as visited
  visited.add(start);

  // perform breadth-first search to find a path from starting to ending n-tersection
  Queue<int[]> queue = new LinkedList<>();
  queue.add(start);
  while (!queue.isEmpty()) {
    int[] current = queue.remove();
    if (current[0] == end[0] && current[1] == end[1]) {
      return "can be travelled";
    }
    for (int[] adjacent : getAdjacentNtersections(current, paths)) {
      if (!visited.contains(adjacent)) {
        queue.add(adjacent);
        visited.add(adjacent);
      }
    }
  }

  // no path found, return "cannot be travelled"
  return "cannot be travelled";
}

