private static List<int[]> getAdjacentNtersections(int[] ntersection, int[][] paths) {
  List<int[]> adjacent = new ArrayList<>();
  for (int[] path : paths) {
    if (path[0] == ntersection[0] || path[1] == ntersection[1]) {
      int[] adjacentNtersection = new int[] {path[0], path[1]};
      if (!adjacent.contains(adjacentNtersection)) {
        adjacent.add(adjacentNtersection);
      }
    }
  }
  return adjacent;
}

