public static String convertDatesToWeekdays(String date) {
    String[] splitDate = date.split(" ");
    int month = Integer.parseInt(splitDate[0]);
    int day = Integer.parseInt(splitDate[1]);
    int year = Integer.parseInt(splitDate[2]);

    int weekday = 0; // 0=Sunday, 1=Monday, 2=Tuesday, ..., 6=Saturday
    if (month < 3) {
        year--;
    }

    int a = year % 100;
    int b = year / 100;
    int c = year % 400;
    int d = b / 4;
    int e = b % 4;
    int f = (b + 8) / 25;
    int g = (b - f + 1) / 3;
    int h = (19*a + b - d - g + 15) % 30;
    int i = c / 4;
    int k = c % 4;
    int l = (32 + e + 2*i - h - k) % 7;
    int m = (a + 11*h + 22*l) / 451;
    int month1 = h + l - 7*m + 114;

    if (month1 <= 31) {
        weekday = month1 % 7;
    } else {
        weekday = (month1 - 31) % 7;
    }

    return weekday;
}
