public static int squarePermutations(int[] A) {
    // Base case: if A is empty or has only one element, return 1
    if (A.length == 0 || A.length == 1) {
        return 1;
    }

    // Initialize variables to keep track of the number of square permutations and the current permutation
    int numSquarePermutations = 0;
    int[] currentPermutation = new int[A.length];
    for (int i = 0; i < A.length; i++) {
        currentPermutation[i] = A[i];
    }

    // Iterate through all possible permutations and count the number of square permutations
    do {
        // Check if the current permutation is a square permutation
        boolean isSquarePermutation = true;
        for (int i = 0; i < A.length - 1; i++) {
            if (!isPerfectSquare((A[i] + A[i + 1]))) {
                isSquarePermutation = false;
                break;
            }
        }

        // If the current permutation is a square permutation, increment the number of square permutations
        if (isSquarePermutation) {
            numSquarePermutations++;
        }
    } while (nextPermutation(currentPermutation));

    return numSquarePermutations;
}

private static boolean nextPermutation(int[] permutation) {
    boolean nextPermutationFound = false;
    for (int i = permutation.length - 2; i >= 0; i--) {
        if (permutation[i] < permutation[i + 1]) {
            // Swap the current element with the next greater element
            int temp = permutation[i];
            permutation[i] = permutation[i + 1];
            permutation[i + 1] = temp;

            // Reverse the remaining elements
            nextPermutationFound = true;
            int j = permutation.length - 1;
            while (i < j) {
                temp = permutation[i];
                permutation[i] = permutation[j];
                permutation[j] = temp;
                i++;
                j--;
            }
            break;
        }
    }
    return nextPermutationFound;
}

