public static int findSmallestInteger(int n) {
    int[] digits = new int[10];
    int smallest = -1;

    // Collect the digits of the input number
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    // Find the smallest rearranged number
    for (int i = 1; i < 10; i++) {
        if (digits[i] > 0) {
            smallest = i;
            break;
        }
    }

    // Rearrange the digits to form the smallest number
    int num = 0;
    for (int i = 0; i < 10; i++) {
        while (digits[i] > 0) {
            num = num * 10 + i;
            digits[i]--;
        }
    }

    // Check if the rearranged number is indeed greater than the input
    if (num > smallest) {
        return num;
    } else {
        return -1;
    }
}
