    char lastChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == lastChar) {
            energy++;
        } else {
            energy = 1;
        }
        lastChar = s.charAt(i);
    }
    return energy;
}
